struct wedge_split {
    unsigned short old_wedge_id;
    unsigned short new_wedge_id;
    uint_vector faces_for_split;
    wedge_split(const wedge_split&);
    wedge_split& operator=(const wedge_split& x) {
        old_wedge_id = x.old_wedge_id;
        new_wedge_id = x.new_wedge_id;
        faces_for_split = x.faces_for_split;
        return *this;
    }
    ~wedge_split();
};

extern "C" wedge_split *allocate_wedges(size_t)
    __asm__("_M_allocate__t12my_allocator1Z11wedge_splitUi");
extern "C" void deallocate_wedges(wedge_split *, size_t)
