extern "C" wedge_split *copy_wedges(
    const wedge_split *, const wedge_split *, wedge_split *)
    __asm__("__uninitialized_copy_aux__H2ZPC11wedge_splitZP11wedge_split_X01X01X11G12__false_type_X11");

struct wedge_vector {
    wedge_split *start;
    wedge_split *finish;
    wedge_split *end_of_storage;

    wedge_vector& operator=(const wedge_vector&)
        __asm__("__as__t6vector2Z11wedge_splitZt12my_allocator1Z11wedge_splitRCt6vector2Z11wedge_splitZt12my_allocator1Z11wedge_split");
};

wedge_vector& wedge_vector::operator=(const wedge_vector& x) {
    if (&x != this) {
        size_t xlen = x.finish - x.start;
        if (xlen > size_t(end_of_storage - start)) {
            wedge_split *tmp = xlen ? allocate_wedges(xlen) : 0;
            copy_wedges(x.start, x.finish, tmp);
            for (wedge_split *p = start; p != finish; ++p)
                p->~wedge_split();
            deallocate_wedges(start, end_of_storage - start);
            start = tmp;
            end_of_storage = start + xlen;
        } else if (size_t(finish - start) >= xlen) {
            wedge_split *first = x.start;
            wedge_split *result = start;
            while (first != x.finish) {
                *result = *first;
                ++first;
                ++result;
            }
            for (wedge_split *p = result; p != finish; ++p)
                p->~wedge_split();
        } else {
            wedge_split *middle = x.start + (finish - start);
            wedge_split *first = x.start;
            wedge_split *result = start;
            while (first != middle) {
                *result = *first;
                ++first;
                ++result;
            }
            copy_wedges(middle, x.finish, finish);
        }
        finish = start + xlen;
    }
    return *this;
}
